def card(work):
    samples = {'eg': 'انا مش فاهم ازاي ده حصل دلوقتي', 'lev': 'شو صار هلق؟ كتير منيح', 'gulf': 'شلون الحال؟ وايد زين', 'mag': 'عجبني برشا والله بزاف', 'msa': 'ذهب الطالب إلى المكتبة صباحا', 'mixed': 'انا مش فاهم شو صار هلق'}
    r = {k: dialect_scores(v) for k, v in samples.items()}
    save(work, 'dialects.json', {k: {'dialect': v[0], 'hits': v[1], 'mixed': v[2]} for k, v in r.items()})
    return [eq('dialects identified', [r[k][0] for k in ('eg', 'lev', 'gulf', 'mag', 'msa')], ['egyptian', 'levantine', 'gulf', 'maghrebi', 'msa']), truth('one-spelling register kept: pure samples not mixed', not any((r[k][2] for k in ('eg', 'lev', 'gulf', 'mag')))), truth('dialect leak inside one reply flagged', r['mixed'][2], r['mixed'][1])]

def card(task, wd):
    s = 'مُحَمَّدٌ يَقْرَأُ القُرْآنَ'
    bw = ar2bw(s)
    back = bw2ar(bw)
    keep = {'محمد صلاح': 'Mohamed Salah', 'كوزيف': 'KOSIF'}

    def for_readers(text):
        for ar, latin in keep.items():
            text = text.replace(ar, '\x00%s\x00' % latin)
        parts = text.split('\x00')
        return ''.join((p if i % 2 else ar2bw(p) for i, p in enumerate(parts)))
    reader = for_readers('سجل محمد صلاح هدفا مع كوزيف')

    def arabizi(text):
        return bool(re.search('[A-Za-z]+[2357][A-Za-z]*', text))
    lossy = ''.join(({'ُ': '', 'َ': '', 'ّ': '', 'ٌ': '', 'ْ': '', 'ِ': ''}.get(c, c) for c in s))
    out = write_json(wd, 'translit.json', {'source': s, 'buckwalter': bw, 'round_trip': back, 'reader': reader, 'arabizi_needs_confirmation': arabizi('ana 3ayez a7ki m3ak')})
    return ([check("Buckwalter output matches the card's known answer", bw == 'muHama~dN yaqora>u Alquro|na', bw, 'muHama~dN yaqora>u Alquro|na'), check('round trip is exact', back == s, back, s), check('names keep their own Latin spelling', 'Mohamed Salah' in reader and 'KOSIF' in reader and ('mHmd' not in reader), reader), check('Arabizi chat is flagged for confirmation, a name is not', arabizi('ana 3ayez a7ki m3ak') and (not arabizi('Mohamed Salah'))), check('negative control: a diacritic-dropping romanizer does not round-trip', bw2ar(ar2bw(lossy)) != s, ar2bw(lossy), '!= source')], [out])

def card(work):
    cases = {'ثلاثة أيام': 0, 'ثلاث أيام': 1, 'ثلاث ساعات': 0, 'ثلاثة ساعات': 1, 'حضر الطلاب': 0, 'حضروا الطلاب': 1, 'خمسة عشر يوما': 0, 'خمسة عشر أياما': 1, 'أجّلت اللجنة الاجتماع': 0, 'أجّل اللجنة الاجتماع': 1}
    got = {s: agreement_errors(s) for s in cases}
    save(work, 'agreement.json', got)
    return [eq('error counts per sentence', {s: len(v) for s, v in got.items()}, cases), truth('3-10 gender reversal explained', 'ثلاثة' in got['ثلاث أيام'][0]), truth('verb-subject rule explained', 'singular' in got['حضروا الطلاب'][0])]
